package org.humanjourney.core.juice;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import org.mockito.MockedStatic;
import java.util.*;
import net.minecraft.SharedConstants;
import net.minecraft.server.Bootstrap;
import net.minecraft.server.level.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.crafting.*;
import net.minecraft.world.inventory.*;
import net.minecraft.world.entity.player.Player;
import net.minecraft.core.component.DataComponents;
import org.humanjourney.core.water.*;
class JuiceQuantityTest {
 static MockedStatic<net.minecraftforge.fml.ModLoader> loader;
 @BeforeAll static void init(){loader=mockStatic(net.minecraftforge.fml.ModLoader.class);loader.when(net.minecraftforge.fml.ModLoader::get).thenReturn(mock(net.minecraftforge.fml.ModLoader.class));SharedConstants.tryDetectVersion();Bootstrap.bootStrap();}
 @AfterAll static void close(){loader.close();}
 MockedStatic<WaterContainers> water;MockedStatic<JuiceBottles> bottles;JuiceDefinition nativeDef;
 @BeforeEach void setup(){nativeDef=new JuiceDefinition(2,"fixture",new JuiceDefinition.Bottle(false,"minecraft:glass_bottle",null,"minecraft:glass_bottle"),new JuiceDefinition.Ingredient(null,"fixture:materials",Set.of("minecraft:sand","minecraft:red_sand")),2,8,"Fixture Canteen",1);JuiceStore.accept(JuiceCatalog.of(List.of(nativeDef)),"unit");water=mockStatic(WaterContainers.class,CALLS_REAL_METHODS);water.when(()->WaterContainers.kind(any(ItemStack.class))).thenAnswer(i->{ItemStack s=i.getArgument(0);if(s==null||JuiceState.marked(s))return null;if(s.is(Items.WOODEN_PICKAXE)||s.is(Items.STONE_PICKAXE))return new WaterContainers.Kind(SaltWater.marked(s)?WaterPolicy.Quality.SALT:WaterPolicy.Quality.PURIFIED,s.is(Items.WOODEN_PICKAXE)?"leather":"iron");return i.callRealMethod();});bottles=mockStatic(JuiceBottles.class,CALLS_REAL_METHODS);bottles.when(()->JuiceBottles.purified(any(ItemStack.class))).thenAnswer(i->{ItemStack s=i.getArgument(0);return s!=null&&s.is(Items.POTION)&&!SaltWater.marked(s)&&!JuiceState.marked(s);});bottles.when(()->JuiceBottles.carrier(any(ItemStack.class))).thenAnswer(i->{ItemStack s=i.getArgument(0);return s!=null&&s.is(Items.HONEY_BOTTLE);});bottles.when(()->JuiceBottles.create(any(ItemStack.class),any(JuiceDefinition.class))).thenAnswer(i->{ItemStack s=i.getArgument(0);JuiceDefinition d=i.getArgument(1);if(s==null||d==null)return ItemStack.EMPTY;var out=s.transmuteCopy(d.bottle().custom()?Items.HONEY_BOTTLE:Items.GLASS_BOTTLE,1);if(d.bottle().custom())JuiceState.setBottle(out,d);return out;});}
 @AfterEach void reset(){bottles.close();water.close();JuiceStore.reset();}
 ItemStack can(){var s=new ItemStack(Items.WOODEN_PICKAXE);s.set(DataComponents.MAX_DAMAGE,5);s.setDamageValue(0);return s;}
 CraftingContainer grid(int width,ItemStack... stacks){var menu=new AbstractContainerMenu(null,0){public ItemStack quickMoveStack(Player p,int i){return ItemStack.EMPTY;}public boolean stillValid(Player p){return true;}};var c=new TransientCraftingContainer(menu,width,stacks.length/width);for(int i=0;i<stacks.length;i++)c.setItem(i,stacks[i].copy());return c;}
 void consume(CraftingContainer c,JuiceCrafting.Plan p){for(int i=0;i<c.getContainerSize();i++)JuiceCrafting.remove(c,p,i,1);}
 @Test void oneUnitInsufficientAndEightInOneStackWorks(){assertNull(JuiceCrafting.plan(grid(2,can(),new ItemStack(Items.SAND),ItemStack.EMPTY,ItemStack.EMPTY).asCraftInput(),false));var c=grid(2,can(),new ItemStack(Items.SAND,8),ItemStack.EMPTY,ItemStack.EMPTY);assertNotNull(JuiceCrafting.forGrid(c,false));}
 @Test void excessStackNormalTakeConsumesExactlyEight(){var c=grid(2,can(),new ItemStack(Items.SAND,20),ItemStack.EMPTY,ItemStack.EMPTY);var p=JuiceCrafting.forGrid(c,false);consume(c,p);assertEquals(12,c.getItem(1).getCount());assertTrue(c.getItem(0).isEmpty());}
 @Test void splitAndMixedTagMembersConsumeExactBudget(){var c=grid(2,can(),new ItemStack(Items.SAND,4),new ItemStack(Items.RED_SAND,6),ItemStack.EMPTY);var p=JuiceCrafting.forGrid(c,false);assertEquals(List.of(1,4,4,0),p.units());consume(c,p);assertTrue(c.getItem(1).isEmpty());assertEquals(2,c.getItem(2).getCount());}
 @Test void eightSeparateCellsAreValid(){var items=new ItemStack[9];items[0]=can();for(int i=1;i<9;i++)items[i]=new ItemStack(Items.SAND);var c=grid(3,items);var p=JuiceCrafting.forGrid(c,false);consume(c,p);assertTrue(c.isEmpty());}
 @Test void unrelatedExtraRejectsBothRecipes(){assertNull(JuiceCrafting.plan(grid(2,can(),new ItemStack(Items.SAND,8),new ItemStack(Items.BONE),ItemStack.EMPTY).asCraftInput(),false));assertNull(JuiceCrafting.plan(grid(2,new ItemStack(Items.POTION),new ItemStack(Items.SAND,8),new ItemStack(Items.BONE),ItemStack.EMPTY).asCraftInput(),true));}
 @Test void fewerRequiredUnitsThanOccupiedCellsDoNotOverConsume(){var c=grid(2,new ItemStack(Items.POTION),new ItemStack(Items.SAND),new ItemStack(Items.SAND),new ItemStack(Items.RED_SAND));var p=JuiceCrafting.forGrid(c,true);assertEquals(List.of(1,1,1,0),p.units());consume(c,p);assertEquals(1,c.getItem(3).getCount());}
 @Test void bottleAndCanteenCostsRemainIndependent(){var b=grid(2,new ItemStack(Items.POTION),new ItemStack(Items.SAND,8),ItemStack.EMPTY,ItemStack.EMPTY);assertEquals(2,JuiceCrafting.forGrid(b,true).units().get(1));var c=grid(2,can(),new ItemStack(Items.SAND,8),ItemStack.EMPTY,ItemStack.EMPTY);assertEquals(8,JuiceCrafting.forGrid(c,false).units().get(1));}
 @Test void repeatedShiftStyleTakeStopsAtTrueResourceLimit(){var c=grid(2,new ItemStack(Items.POTION,16),new ItemStack(Items.SAND,20),ItemStack.EMPTY,ItemStack.EMPTY);int made=0;JuiceCrafting.Plan p;while((p=JuiceCrafting.forGrid(c,true))!=null){assertTrue(p.output().is(Items.GLASS_BOTTLE));consume(c,p);assertTrue(++made<=10);}assertEquals(10,made);assertEquals(6,c.getItem(0).getCount());assertTrue(c.getItem(1).isEmpty());}
 @Test void carrierAndPartialOrSaltRulesRetained(){assertNull(JuiceCrafting.plan(grid(2,new ItemStack(Items.GLASS_BOTTLE),new ItemStack(Items.SAND,8),ItemStack.EMPTY,ItemStack.EMPTY).asCraftInput(),true));var p=can();p.setDamageValue(1);assertNull(JuiceCrafting.plan(grid(2,p,new ItemStack(Items.SAND,8),ItemStack.EMPTY,ItemStack.EMPTY).asCraftInput(),false));var salt=can();SaltWater.set(salt,true);assertNull(JuiceCrafting.plan(grid(2,salt,new ItemStack(Items.SAND,8),ItemStack.EMPTY,ItemStack.EMPTY).asCraftInput(),false));var j=can();JuiceState.set(j,nativeDef);assertNull(JuiceCrafting.plan(grid(2,j,new ItemStack(Items.SAND,8),ItemStack.EMPTY,ItemStack.EMPTY).asCraftInput(),false));}
 @Test void customModeOutputsIdentityAndSameNativeSource(){var d=new JuiceDefinition(2,"custom",new JuiceDefinition.Bottle(true,null,"Fixture Bottle","minecraft:glass_bottle"),nativeDef.ingredient(),2,8,"Fixture Custom Canteen",1);JuiceStore.accept(JuiceCatalog.of(List.of(d)),"custom");var p=JuiceCrafting.plan(grid(2,new ItemStack(Items.POTION),new ItemStack(Items.SAND,2),ItemStack.EMPTY,ItemStack.EMPTY).asCraftInput(),true);assertTrue(p.output().is(Items.HONEY_BOTTLE));assertEquals("custom",JuiceState.id(p.output()));assertEquals("Fixture Bottle",JuiceState.display(p.output()));assertEquals("minecraft:glass_bottle",JuiceBottles.definition(p.output()).effectSourceItem());}
 @Test void nativeSlotHooksKeepQuantityAfterQuickCraftClearsUsedRecipe()throws Exception{var c=grid(2,can(),new ItemStack(Items.SAND,20),ItemStack.EMPTY,ItemStack.EMPTY);var result=new ResultContainer();var recipe=new JuiceRecipe(CraftingBookCategory.MISC);result.setRecipeUsed(new RecipeHolder<>(net.minecraft.resources.ResourceKey.create(net.minecraft.core.registries.Registries.RECIPE,net.minecraft.resources.ResourceLocation.parse("fixture:juice")),recipe));result.setItem(0,recipe.assemble(c.asCraftInput(),null));var slot=new org.humanjourney.core.juice.mixin.JuiceResultSlotMixin(result,0,0,0){};var field=org.humanjourney.core.juice.mixin.JuiceResultSlotMixin.class.getDeclaredField("craftSlots");field.setAccessible(true);field.set(slot,c);var player=mock(ServerPlayer.class);when(player.level()).thenReturn(mock(ServerLevel.class));assertTrue(slot.mayPickup(player));invoke(slot,"hjRememberQuickCraft",new Class[]{ItemStack.class,int.class,org.spongepowered.asm.mixin.injection.callback.CallbackInfo.class},ItemStack.EMPTY,1,new org.spongepowered.asm.mixin.injection.callback.CallbackInfo("unit",false));result.setRecipeUsed((RecipeHolder<?>)null);invoke(slot,"hjBegin",new Class[]{Player.class,ItemStack.class,org.spongepowered.asm.mixin.injection.callback.CallbackInfo.class},player,ItemStack.EMPTY,new org.spongepowered.asm.mixin.injection.callback.CallbackInfo("unit",false));for(int i=0;i<c.getContainerSize();i++)invoke(slot,"hjConsume",new Class[]{CraftingContainer.class,int.class,int.class},c,i,1);assertEquals(12,c.getItem(1).getCount());invoke(slot,"hjEnd",new Class[]{Player.class,ItemStack.class,org.spongepowered.asm.mixin.injection.callback.CallbackInfo.class},player,ItemStack.EMPTY,new org.spongepowered.asm.mixin.injection.callback.CallbackInfo("unit",false));}
 static Object invoke(Object target,String method,Class<?>[] signature,Object... args)throws Exception{var m=org.humanjourney.core.juice.mixin.JuiceResultSlotMixin.class.getDeclaredMethod(method,signature);m.setAccessible(true);return m.invoke(target,args);}
 @Test void positionedRemaindersMapToTheCorrectNativeGridCells(){var full=net.minecraft.core.NonNullList.withSize(9,ItemStack.EMPTY);full.set(8,new ItemStack(Items.BUCKET));var positioned=new CraftingInput.Positioned(CraftingInput.of(1,1,List.of(new ItemStack(Items.MILK_BUCKET))),2,2);assertTrue(JuiceCrafting.project(full,3,positioned).getFirst().is(Items.BUCKET));}
 @Test void nativeRemaindersScalePerConsumedUnitAndNeverExceedStackLimit(){var source=spy(new ItemStack(Items.SAND,20));var unit=spy(new ItemStack(Items.SAND));doReturn(unit).when(source).copyWithCount(1);doReturn(new ItemStack(Items.WOODEN_SWORD)).when(unit).getCraftingRemainder();var input=CraftingInput.of(2,1,List.of(can(),source));var p=new JuiceCrafting.Plan(nativeDef,0,List.of(1,8),can());var remainders=JuiceCrafting.remainders(input,p);assertEquals(1,remainders.grid().get(1).getCount());assertEquals(7,remainders.overflow().size());assertTrue(remainders.overflow().stream().allMatch(s->s.getCount()==1));}
}
